function freshDb(): Db {
  const db = openDatabase(':memory:');
  seedDatabase(db);
  return db;
}

function appFor(db: Db): Express {
  return createApp(db, { frontendDist: null });
}

function countRows(db: Db, table: string): number {
  return (db.prepare(`SELECT COUNT(*) AS n FROM ${table}`).get() as { n: number }).n;
}

describe('migrations', () => {
  it('are repeatable and create the contract tables', () => {
    const db = openDatabase(':memory:');
    migrate(db);
    migrate(db);
    const tables = (
      db.prepare("SELECT name FROM sqlite_master WHERE type='table'").all() as { name: string }[]
    ).map((r) => r.name);
    for (const table of [
      'workbooks',
      'worksheets',
      'cells',
      'validation_rules',
      'filters',
      'pivots',
      'schema_migrations',
    ]) {
      expect(tables).toContain(table);
    }
    expect(countRows(db, 'schema_migrations')).toBe(1);
  });
});

describe('seed', () => {
