export class ApiClientError extends Error {
  status: number; code: string;
  constructor(status: number, code: string, message: string) { super(message); this.status = status; this.code = code; }
}

async function request<T>(path: string, init?: RequestInit): Promise<T> {
  let res: Response;
  try {
    res = await fetch(path, { headers: { 'Content-Type': 'application/json' }, ...init });
  } catch (e) {
    throw new ApiClientError(0, 'NETWORK_ERROR', 'Could not reach the server. Please retry.');
  }
  const text = await res.text();
  let body: unknown = null;
  if (text) { try { body = JSON.parse(text) } catch { body = null } }
  if (!res.ok) {
    const err = (body as ApiErrorBody | null)?.error;
    throw new ApiClientError(res.status, err?.code ?? 'ERROR', err?.message ?? `Request failed with status ${res.status}`);
  }
  return body as T;
}
```
Note: setting Content-Type on GET is harmless.

