import { useEffect, useState } from 'react';

export interface FormulaBarProps {
  /** A1-style coordinate of the selected cell. */
  coordinate: string;
  /** Raw content of the selected cell (formula text stays raw). */
  value: string;
  onCommit: (value: string) => void;
}

/**
 * Name box + formula bar. The text box is labelled exactly "Formula bar"
 * (contract §3) and stays in two-way sync with the selected cell: committing
 * here writes through the same cells endpoint the grid uses.
 */
export function FormulaBar({ coordinate, value, onCommit }: FormulaBarProps) {
  const [draft, setDraft] = useState(value);

  useEffect(() => {
    setDraft(value);
  }, [value, coordinate]);

  const commit = () => {
    if (draft !== value) onCommit(draft);
  };

  return (
    <div className="flex items-stretch border-b-1 border-sheet-border bg-white">
      <input
        readOnly
        aria-label="Name box"
        value={coordinate}
        className="w-24 shrink-0 border-r-1 border-sheet-border bg-white px-2 py-1 text-center text-sm text-sheet-text outline-none"
      />
      <div className="flex w-8 shrink-0 items-center justify-center border-r-1 border-sheet-border text-sm italic text-sheet-muted">
        fx
      </div>
      <input
        aria-label="Formula bar"
        value={draft}
        onChange={(event) => setDraft(event.target.value)}
        onKeyDown={(event) => {
          if (event.key === 'Enter') {
            event.preventDefault();
            commit();
          } else if (event.key === 'Escape') {
            event.preventDefault();
            setDraft(value);
          }
        }}
        onBlur={commit}
        className="h-8 w-full min-w-0 flex-1 px-2 text-sm text-sheet-text outline-none focus:outline-2 focus:outline-sheet-accent focus:-outline-offset-2"
      />
    </div>
  );
}

import type { WorksheetSnapshot } from '../../shared/types';

export interface WorksheetTabsProps {
  worksheets: WorksheetSnapshot[];
  activeWorksheetId: string;
  onSelect: (worksheetId: string) => void;
}

/**
 * Bottom worksheet tab bar. Tabs use the ARIA `tab` role with an exact
 * `aria-selected` state driven by the persisted `last_active` flag. Adding,
 * renaming and deleting worksheets belongs to the worksheet sub-issue.
 */
export function WorksheetTabs({ worksheets, activeWorksheetId, onSelect }: WorksheetTabsProps) {
  return (
    <div
      role="tablist"
      aria-label="Worksheets"
      className="flex items-center gap-1 border-t-1 border-sheet-border bg-sheet-header px-2 py-1"
    >
      {worksheets.map((worksheet) => {
        const active = worksheet.id === activeWorksheetId;
        return (
          <button
            key={worksheet.id}
            type="button"
            role="tab"
            id={`worksheet-tab-${worksheet.id}`}
            aria-selected={active}
            aria-controls="worksheet-grid-panel"
            onClick={() => onSelect(worksheet.id)}
            className={
              'rounded-t px-3 py-1 text-sm ' +
              (active
                ? 'bg-white font-medium text-sheet-accent shadow-sm'
                : 'text-sheet-muted hover:bg-#e8eaed')
            }
          >
            {worksheet.name}
          </button>
        );
      })}
    </div>
  );
}

import type { ReactNode } from 'react';

export interface ErrorBannerProps {
  message: string | null;
  onDismiss?: () => void;
}

/** Visible, announced error surface for failed commits and load errors. */
export function ErrorBanner({ message, onDismiss }: ErrorBannerProps): ReactNode {
  if (!message) return null;
  return (
    <div
      role="alert"
      className="flex items-center justify-between gap-4 border-b-1 border-#f5c6c2 bg-#fce8e6 px-3 py-2 text-sm text-sheet-danger"
    >
      <span>{message}</span>
      {onDismiss ? (
        <button type="button" onClick={onDismiss} className="text-sheet-danger underline">
          Dismiss
        </button>
      ) : null}
    </div>
  );
}

