import { describe, expect, it } from 'vitest';
import { cellKey, columnLabel, parseCoordinate, toCoordinate } from './coordinates';
import { lastUpdatedText } from './format';
import { A1_SELECTION, isSelected, normalizeSelection, sameSelection, selectionSize } from './selection';

describe('coordinates', () => {
  it('converts column indexes to spreadsheet labels', () => {
    expect(columnLabel(0)).toBe('A');
    expect(columnLabel(25)).toBe('Z');
    expect(columnLabel(26)).toBe('AA');
    expect(columnLabel(27)).toBe('AB');
  });

  it('builds the accessible coordinate for a cell', () => {
    expect(toCoordinate(0, 0)).toBe('A1');
    expect(toCoordinate(2, 1)).toBe('B3');
    expect(cellKey(2, 1)).toBe('2:1');
  });

  it('parses coordinates back to 0-based indexes', () => {
    expect(parseCoordinate('A1')).toEqual({ row: 0, col: 0 });
    expect(parseCoordinate('aa10')).toEqual({ row: 9, col: 26 });
    expect(parseCoordinate('1A')).toBeNull();
  });
});

describe('selection', () => {
  it('normalizes a rectangle regardless of drag direction', () => {
    expect(normalizeSelection({ row: 3, col: 2 }, { row: 1, col: 0 })).toEqual({
      r1: 1,
      c1: 0,
      r2: 3,
      c2: 2,
      anchor: { row: 3, col: 2 },
    });
  });

  it('reports exactly the cells inside the rectangle', () => {
    const selection = normalizeSelection({ row: 0, col: 0 }, { row: 1, col: 2 });
    expect(selectionSize(selection)).toBe(6);
    expect(isSelected(selection, 1, 2)).toBe(true);
    expect(isSelected(selection, 2, 0)).toBe(false);
    expect(isSelected(A1_SELECTION, 0, 0)).toBe(true);
    expect(isSelected(A1_SELECTION, 0, 1)).toBe(false);
  });

  it('compares rectangles including the anchor', () => {
    const a = normalizeSelection({ row: 0, col: 0 }, { row: 0, col: 1 });
    const b = normalizeSelection({ row: 0, col: 1 }, { row: 0, col: 0 });
    expect(sameSelection(a, b)).toBe(false);
    expect(sameSelection(a, { ...a })).toBe(true);
  });
});

describe('last updated formatting', () => {
  it('renders the shared "Last updated:" text from the same field', () => {
    expect(lastUpdatedText('2026-09-29T04:38:45.142Z')).toBe('Last updated: Sep 29, 2026, 4:38 AM UTC');
  });

  it('falls back to the raw value for unparseable timestamps', () => {
    expect(lastUpdatedText('not-a-date')).toBe('Last updated: not-a-date');
  });
});

import { describe, expect, it, vi } from 'vitest';
import { fireEvent, render, screen } from '@testing-library/react';
import { Grid } from './Grid';
import type { GridProps } from './Grid';
import { A1_SELECTION, normalizeSelection } from '../lib/selection';

function renderGrid(overrides: Partial<GridProps> = {}) {
  const props: GridProps = {
    rowCount: 2,
    colCount: 3,
    cells: new Map([
      ['0:0', 'Region'],
      ['1:1', '800'],
    ]),
    selection: A1_SELECTION,
    editing: null,
    onSelectionChange: vi.fn(),
    onStartEdit: vi.fn(),
    onCommitEdit: vi.fn(),
    onCancelEdit: vi.fn(),
    ...overrides,
  };
  render(<Grid {...props} />);
  return props;
}

describe('Grid ARIA contract', () => {
  it('exposes the grid, its accessible name and multiselectability', () => {
    renderGrid();
    const grid = screen.getByRole('grid', { name: 'Worksheet grid' });
    expect(grid.getAttribute('aria-multiselectable')).toBe('true');
  });

  it('names every cell by its coordinate and keeps aria-selected exact', () => {
    renderGrid();
    expect(screen.getByRole('gridcell', { name: 'A1' }).textContent).toBe('Region');
    expect(screen.getByRole('gridcell', { name: 'B2' }).textContent).toBe('800');
    expect(screen.getByRole('gridcell', { name: 'A1' }).getAttribute('aria-selected')).toBe('true');
    for (const coordinate of ['B1', 'C1', 'A2', 'B2', 'C2']) {
      expect(screen.getByRole('gridcell', { name: coordinate }).getAttribute('aria-selected')).toBe(
        'false',
      );
    }
  });

  it('marks exactly the cells of a rectangular selection', () => {
    renderGrid({ selection: normalizeSelection({ row: 0, col: 0 }, { row: 1, col: 2 }) });
    const selected = screen
      .getAllByRole('gridcell')
      .filter((cell) => cell.getAttribute('aria-selected') === 'true');
    expect(selected).toHaveLength(6);
  });

  it('provides row and column headers with accessible names', () => {
    renderGrid();
    expect(screen.getByRole('rowheader', { name: '1' }).textContent).toBe('1');
    expect(screen.getByRole('rowheader', { name: '2' }).textContent).toBe('2');
    expect(screen.getByRole('columnheader', { name: 'A' })).toBeTruthy();
    expect(screen.getByRole('columnheader', { name: 'C' })).toBeTruthy();
  });
});

describe('Grid interaction', () => {
  it('starts inline editing on double click and commits on Enter', () => {
    const props = renderGrid();
    fireEvent.doubleClick(screen.getByRole('gridcell', { name: 'B1' }));
    const input = screen.getByRole('textbox', { name: 'Edit B1' }) as HTMLInputElement;
    fireEvent.change(input, { target: { value: '42' } });
    fireEvent.keyDown(input, { key: 'Enter' });
    expect(props.onCommitEdit).toHaveBeenCalledWith({ row: 0, col: 1 }, '42');
  });

  it('cancels inline editing on Escape without committing', () => {
    const props = renderGrid({ editing: { row: 0, col: 1 } });
    const input = screen.getByRole('textbox', { name: 'Edit B1' });
    fireEvent.change(input, { target: { value: 'ignored' } });
    fireEvent.keyDown(input, { key: 'Escape' });
    expect(props.onCancelEdit).toHaveBeenCalledTimes(1);
    expect(props.onCommitEdit).not.toHaveBeenCalled();
  });

  it('writes the rectangle only when the drag finishes', () => {
    const props = renderGrid();
    fireEvent.mouseDown(screen.getByRole('gridcell', { name: 'A1' }));
    fireEvent.mouseOver(screen.getByRole('gridcell', { name: 'B2' }));
    expect(props.onSelectionChange).toHaveBeenLastCalledWith(
      { r1: 0, c1: 0, r2: 1, c2: 1, anchor: { row: 0, col: 0 } },
      false,
    );
    fireEvent.mouseUp(window);
    expect(props.onSelectionChange).toHaveBeenLastCalledWith(
      { r1: 0, c1: 0, r2: 1, c2: 1, anchor: { row: 0, col: 0 } },
      true,
    );
  });
});

