import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { defineConfig, devices } from '@playwright/test';

/**
 * End-to-end checks run against the production shape of the app: the built
 * frontend (`frontend/dist`) served by the backend on one port, exactly like
 * the delivery platform. A throwaway SQLite file is used per run so checks
 * never touch development or delivered data.
 *
 * Run with: bash checks/run-e2e.sh
 */
const PORT = Number(process.env.E2E_PORT ?? 4317);
const DB_PATH =
  process.env.E2E_DB_PATH ??
  path.join(fs.mkdtempSync(path.join(os.tmpdir(), 'sheet-e2e-')), 'app.db');
const BASE_URL = `http://127.0.0.1:${PORT}`;
const browserExecutable = process.env.BROWSER_EXECUTABLE_PATH;

export default defineConfig({
  testDir: './e2e',
  timeout: 90_000,
  expect: { timeout: 15_000 },
  fullyParallel: false,
  workers: 1,
  forbidOnly: Boolean(process.env.CI),
  reporter: process.env.CI ? [['list'], ['html', { open: 'never' }]] : [['list']],
  use: {
    baseURL: BASE_URL,
    trace: 'retain-on-failure',
    screenshot: 'only-on-failure',
    launchOptions: browserExecutable ? { executablePath: browserExecutable } : {},
  },
  projects: [{ name: 'chromium', use: { ...devices['Desktop Chrome'] } }],
  webServer: {
    command: 'node backend/src/index.js',
    url: `${BASE_URL}/api/health`,
    reuseExistingServer: false,
    timeout: 60_000,
    stdout: 'pipe',
    stderr: 'pipe',
    env: {
      HOST: '127.0.0.1',
      PORT: String(PORT),
      DB_PATH,
    },
  },
});

import { expect, test } from '@playwright/test';

/**
 * Base-PR smoke test and template for follow-up acceptance suites:
 * home page → open the seeded workbook → edit a cell → refresh → assert the
 * value persisted and the ARIA selection state is exact.
 */
test.describe('spreadsheet workspace smoke', () => {
  test('home page lists the seeded workbook', async ({ page }) => {
    await page.goto('/');
    await expect(page.getByRole('heading', { name: 'Workbooks' })).toBeVisible();
    const entry = page.getByRole('link', { name: 'Q3 Sales', exact: true });
    await expect(entry).toBeVisible();
    await expect(page.getByText('Last updated: ').first()).toBeVisible();
  });

  test('grid, editing, refresh persistence and ARIA state', async ({ page }) => {
    await page.goto('/');
    await page.getByRole('link', { name: 'Q3 Sales', exact: true }).click();
    await expect(page).toHaveURL(/\/workbook\/.+/);

    const grid = page.getByRole('grid', { name: 'Worksheet grid' });
    await expect(grid).toBeVisible();
    await expect(grid).toHaveAttribute('aria-multiselectable', 'true');

    // Seeded content is rendered, including numbers and text.
    await expect(page.getByRole('gridcell', { name: 'A1' })).toHaveText('Region');
    await expect(page.getByRole('gridcell', { name: 'B2' })).toHaveText('1200');
    await expect(page.getByRole('gridcell', { name: 'C4' })).toHaveText('Open');
    // Empty seed cells still exist with an exact aria-selected state.
    await expect(page.getByRole('gridcell', { name: 'A5' })).toBeEmpty();
    await expect(page.getByRole('gridcell', { name: 'A5' })).toHaveAttribute('aria-selected', 'false');

    // Worksheet tabs follow last_active.
    await expect(page.getByRole('tab', { name: 'Sheet1' })).toHaveAttribute('aria-selected', 'true');
    await expect(page.getByRole('tab', { name: 'Sheet2' })).toHaveAttribute('aria-selected', 'false');

    // Single-cell selection toggles aria-selected exactly.
    await expect(page.getByRole('gridcell', { name: 'A1' })).toHaveAttribute('aria-selected', 'true');
    await page.getByRole('gridcell', { name: 'B2' }).click();
    await expect(page.getByRole('gridcell', { name: 'B2' })).toHaveAttribute('aria-selected', 'true');
    await expect(page.getByRole('gridcell', { name: 'A1' })).toHaveAttribute('aria-selected', 'false');

    // Formula bar mirrors the selected cell and writes back.
    const formulaBar = page.getByRole('textbox', { name: 'Formula bar' });
    await expect(formulaBar).toHaveValue('1200');

    // Inline editing: double click, type, Enter.
    await page.getByRole('gridcell', { name: 'B2' }).dblclick();
    const inlineEditor = page.getByRole('textbox', { name: 'Edit B2' });
    await inlineEditor.fill('1500');
    await inlineEditor.press('Enter');
    await expect(page.getByRole('gridcell', { name: 'B2' })).toHaveText('1500');
    await expect(formulaBar).toHaveValue('1500');

    // Escape cancels an uncommitted inline edit.
    await page.getByRole('gridcell', { name: 'C2' }).dblclick();
    const cancelEditor = page.getByRole('textbox', { name: 'Edit C2' });
    await cancelEditor.fill('discarded');
    await cancelEditor.press('Escape');
    await expect(page.getByRole('gridcell', { name: 'C2' })).toHaveText('Open');

    // Confirmed selection is persisted for the worksheet.
    await page.getByRole('gridcell', { name: 'A4' }).click();
    await expect(page.getByRole('gridcell', { name: 'A4' })).toHaveAttribute('aria-selected', 'true');

    // Refresh: edited value and stored selection survive, seed rows are intact.
    await page.reload();
    await expect(page.getByRole('gridcell', { name: 'B2' })).toHaveText('1500');
    await expect(page.getByRole('gridcell', { name: 'A4' })).toHaveAttribute('aria-selected', 'true');
    await expect(page.getByRole('gridcell', { name: 'A1' })).toHaveAttribute('aria-selected', 'false');
    await expect(page.getByRole('gridcell', { name: 'A2' })).toHaveText('East');

    // Switching worksheets switches the grid and does not modify the source.
    await page.getByRole('tab', { name: 'Sheet2' }).click();
    await expect(page.getByRole('tab', { name: 'Sheet2' })).toHaveAttribute('aria-selected', 'true');
    await expect(page.getByRole('gridcell', { name: 'A1' })).toBeEmpty();
    await page.getByRole('tab', { name: 'Sheet1' }).click();
    await expect(page.getByRole('gridcell', { name: 'A1' })).toHaveText('Region');
    await expect(page.getByRole('gridcell', { name: 'A4' })).toHaveAttribute('aria-selected', 'true');

    // The workbook is still listed on the home page.
    await page.goto('/');
    await expect(page.getByRole('link', { name: 'Q3 Sales', exact: true })).toBeVisible();
  });
});

